import {numberName,choiceNumbers} from './core.js';
import {icon,esc,button,audioButton,companion,showDialog} from './ui.js';
const dots=n=>Array.from({length:n},()=>'<i class="unit" aria-hidden="true"></i>').join('');
function tens(n,groups=Math.floor(n/10)){return `<div class="tens-model" role="img" aria-label="${groups} decenas y ${n-groups*10} unidades sueltas">${Array.from({length:groups},(_,i)=>`<div class="ten reveal-step" style="--i:${i}" title="Una decena: diez unidades">${dots(10)}</div>`).join('')}<div class="units" style="flex-wrap:wrap;max-width:320px">${dots(n-groups*10)}</div></div><p class="muted">${groups} ${groups===1?'decena':'decenas'} · ${n-groups*10} unidades sueltas</p>`;}
function symbol(a){const t=(a.prompt||'').toLowerCase();if(/manzana/.test(t))return '🍎';if(/globo/.test(t))return '🎈';if(/hoja/.test(t))return '🍃';if(/flor/.test(t))return '🌼';if(/pegatina|estrella/.test(t))return '⭐';if(/piedra/.test(t))return '🪨';if(/concha/.test(t))return '🐚';return '●';}
function objects(n,p,{action='count-object',removed=false,base=false,offset=0,emoji='●'}={}){if(!n)return '<p class="notice">No hay objetos: esta cantidad es 0.</p>';let html='<div class="objects">';for(let g=0;g<Math.ceil(n/10);g++){html+='<div class="object-group">';for(let j=g*10;j<Math.min(n,g*10+10);j++){const i=j+offset,selected=(p.touched||[]).includes(i);html+=`<button class="object ${selected?(removed?'removed':'counted'):''} ${p.solutionShown?'reveal-step':''}" style="--i:${j}" ${base?'disabled':''} data-action="${action}" data-value="${i}" aria-label="Objeto ${i+1}${selected?(removed?', retirado':', contado'):''}" aria-pressed="${selected}"><span aria-hidden="true">${emoji}</span>${selected&&!removed?`<small>${p.touched.indexOf(i)+1}</small>`:''}</button>`;}html+='</div>';}return html+'</div>';}
function line(min,max,p,answerable=false,start,finish){return `<div class="numberline" aria-label="Recta numérica del ${min} al ${max}">${Array.from({length:max-min+1},(_,i)=>{const n=min+i;return `<button data-action="${answerable?'line-answer':'line-speak'}" data-value="${n}" class="${String(p.answer)===String(n)?'landed':(p.showSteps&&start!==undefined&&n>=Math.min(start,finish)&&n<=Math.max(start,finish))?'jumped':''}" aria-label="${numberName(n)}${n===start?', punto de partida':''}" ${answerable&&p.correct?'disabled':''}>${n}</button>`;}).join('')}</div>`;}
function numeric(a,p,max){return `<div class="choices numbers">${choiceNumbers(a.answer,max).map(n=>`<button class="choice number" data-action="number-answer" data-value="${n}" ${p.correct?'disabled':''}>${n}</button>`).join('')}</div><details class="keypad" ${p.keypad?'open':''}><summary class="text-button">Prefiero el teclado numérico</summary><label class="answer-display">Respuesta <input id="numeric-answer" inputmode="numeric" pattern="[0-9]*" autocomplete="off" maxlength="3" value="${esc(p.answer)}" ${p.correct?'disabled':''}></label><div class="keys">${[1,2,3,4,5,6,7,8,9,'⌫',0,'✓'].map(n=>`<button data-action="key" data-value="${n}" aria-label="${n==='⌫'?'Borrar':n==='✓'?'Comprobar':n}" ${p.correct?'disabled':''}>${n}</button>`).join('')}</div></details>`;}
function feedback(p){return p.feedback?`<div class="feedback ${p.correct?'success':''}" role="status"><strong>${p.correct?(p.solutionShown?'Vamos a verlo paso a paso.':p.errors?'¡Has vuelto a intentarlo!':'¡Buen trabajo explorando!'):'Vamos a probar con una pista.'}</strong><p>${esc(p.feedback)}</p>${p.correct?button('Continuar '+icon('arrow'),'math-next','small'):button('Ver la solución paso a paso','math-solution','secondary small')}</div>`:'';}
function manipulation(a,p){let html='';const sum=a.kind==='sum';if(sum){html+=`<p><strong>Ya tienes ${a.a}.</strong> Toca los ${a.b} objetos que se añaden.</p><div class="row"><span class="pill">Al principio: ${a.a}</span><span class="pill">Añadidos: ${p.touched.length} de ${a.b}</span></div>${objects(a.a,{touched:[]},{base:true,emoji:symbol(a)})}${a.b?`<p class="muted">Toca cada objeto para llevarlo al grupo.</p>${objects(a.b,p,{action:'operate',emoji:symbol(a)})}`:'<p>No añadimos ninguno. La cantidad se queda igual.</p>'}<p>Ahora en el grupo: <strong>${a.a+p.touched.length}</strong>.</p>`;}else{html+=`<p><strong>Empieza con ${a.a}.</strong> Toca ${a.b} para retirarlos.</p>${objects(a.a,p,{action:'operate',removed:true,emoji:symbol(a)})}<p>Retirados: ${p.touched.length} de ${a.b} · Quedan: <strong>${a.a-p.touched.length}</strong>.</p><p class="muted">Los objetos retirados siguen visibles y tachados para que veas el cambio.</p>`;}return html;}
function arithmeticModel(a,p){const sum=a.kind==='sum';const max=Math.max(a.a,a.answer);return `${p.showHelp||a.mode==='objects'?manipulation(a,p):''}${p.showHelp||a.mode==='line'?`<p>Empieza en ${a.a}. Da ${a.b} saltos hacia ${sum?'delante':'atrás'}.</p>${line(0,max<=10?10:20,p,false,a.a,a.answer)}${button('Mostrar los saltos','show-steps','secondary small')}${p.showSteps?`<p class="notice">${Array.from({length:a.b+1},(_,i)=>a.a+(sum?i:-i)).join(' → ')}. ${a.b===0?'Cero saltos: te quedas en el mismo lugar.':''}</p>`:''}`:''}<div class="equation" aria-label="${a.a} ${sum?'más':'menos'} ${a.b} es igual a ${p.correct?a.answer:'cuánto'}">${a.a} ${sum?'+':'−'} ${a.b} = ${p.correct?a.answer:'?'}</div>`;}
export function renderMath(ctx,view){if(view==='hundred'){const n=ctx.state.tableNumber||1;return `<div class="activity"><div class="activity-top"><a class="text-button" href="#counting">← Volver a contar</a><span class="pill">Exploro los números</span></div><section class="activity-card"><h1>Mi mapa del 1 al 100</h1><p>Toca un número para escucharlo. Cada decena reúne diez números.</p><div class="number-focus" aria-live="polite"><strong>${n}</strong>${numberName(n)} · ${Math.floor(n/10)} decenas y ${n%10} unidades</div><div class="hundred" tabindex="0" aria-label="Tabla del 1 al 100. Desplázate para ver más números.">${Array.from({length:100},(_,i)=>`<button data-action="table" data-value="${i+1}" class="${n===i+1?'selected':''}" aria-label="${numberName(i+1)}" aria-pressed="${n===i+1}">${i+1}</button>`).join('')}</div><p class="audio-note">Si no hay audio, el nombre aparece escrito. También podéis pronunciarlo juntos.</p></section>${companion('Después del 29 llega el 30. ¡Otra decena!')}</div>`;}
 const p=ctx.state.pending;if(p.kind==='guide')return guide(ctx);
 const counting=p.kind==='counting',a=counting?ctx.math.counting.find(x=>x.id===p.id):ctx.math.arithmetic.find(x=>x.id===p.id);p.title=a.title||a.prompt;p.levelIndex=(counting?[20,50,100]:[10,20]).indexOf(counting?a.band:a.range);
 let body=`<p class="instruction">${esc(a.prompt)}</p>${audioButton(a.prompt)}`;
 if(counting){if(a.type==='objects')body+=`${objects(a.target,p,{emoji:symbol(a)})}<p>Has marcado ${p.touched.length} objetos. Toca uno marcado para deshacer.</p>`;
 else if(a.type==='quantity')body+=tens(a.target);
 else if(['series','skip'].includes(a.type))body+=`<div class="series">${a.series.map(x=>`<span class="${p.correct&&x===null?'reveal-step':''}">${x===null?(p.correct?a.answer:'?'):x}</span>`).join('')}</div>`;
 else if(a.type==='neighbors')body+=`<div class="series"><span>${a.side==='before'?'?':a.number}</span><span>→</span><span>${a.side==='after'?'?':a.number}</span></div>`;
 else if(a.type==='line')body+=`<p class="muted">Toca la posición de ${a.number} en la recta.</p>${line(a.min,a.max,p,true)}${button('Comprobar posición','math-check','',p.answer===''||p.correct?'disabled':'')}`;
 else if(a.type==='tens'){const groups=p.grouped??(a.ask==='units'?Math.floor(a.number/10):0);body+=tens(a.number,groups)+button('Agrupar 10 unidades','group-ten','secondary small',a.number-groups*10<10?'disabled':'');}
 else if(a.type==='continue')body+=`<div class="series"><span>${a.number}</span><span>+ ${a.steps} pasos</span><span>${p.correct?a.answer:'?'}</span></div>`;
 if(p.showHelp&&['neighbors','continue','series','skip'].includes(a.type))body+=line(Math.max(0,a.answer-5),Math.min(a.band,a.answer+5),p,false);
 if(a.type!=='line')body+=numeric(a,p,a.band);
 }else{body+=arithmeticModel(a,p)+numeric(a,p,a.range);}
 body+=`<div class="row spacer">${button(icon('help')+' Necesito una pista','math-hint','soft small')}${!counting?button('Objetos y recta','math-help','secondary small')+button('¿Qué significan los signos?','signs','secondary small'):''}</div>${feedback(p)}`;
 return `<div class="activity"><div class="activity-top"><a class="text-button" href="#${counting?'counting':p.kind}">${icon('back')} Guardar y salir</a><span class="pill">${counting?'Contar hasta '+a.band:p.kind==='sum'?'Juntamos y añadimos':'Retiramos y contamos'}</span></div><section class="activity-card"><span class="eyebrow">CUENTO Y CALCULO</span><h1>${esc(counting?a.title:a.mode==='problem'?'Un pequeño problema':p.kind==='sum'?'¿Cuántos hay en total?':'¿Cuántos quedan?')}</h1>${body}</section>${companion(p.kind==='subtract'?'Vamos a contar los que quedan. Puedes tocar cada objeto.':'Puedes contar uno a uno o empezar desde una cantidad que ya conoces.')}</div>`;
}
function guide(ctx){const p=ctx.state.pending,sum=p.id==='sum',a={kind:p.id,a:sum?3:5,b:2,answer:sum?5:3,mode:'objects',prompt:sum?'Tienes tres manzanas. Añade dos manzanas.':'Tienes cinco globos. Retira dos globos.'};const done=p.touched.length===2;return `<div class="activity"><div class="activity-top"><a class="text-button" href="#${p.id}">← Volver</a><span class="pill">Lo hacemos juntas</span></div><section class="activity-card"><h1>${sum?'Sumar es juntar o añadir':'Restar es quitar una parte'}</h1><p class="instruction">${a.prompt}</p>${audioButton(a.prompt+' Toca cada objeto para probar.')}${manipulation(a,p)}<div class="equation">${a.a} ${sum?'+':'−'} 2 = ${done?a.answer:'?'}</div>${done?`<div class="feedback success"><p>${sum?'Tres manzanas y dos manzanas son cinco.':'De cinco globos, retiramos dos y quedan tres.'} A los dos lados del signo igual hay la misma cantidad.</p>${audioButton(sum?'Tres más dos es igual a cinco. Los dos lados representan cinco manzanas.':'Cinco menos dos es igual a tres. Los dos lados representan tres globos.')}</div>`:''}<p>Desde ${a.a}, avanzamos ${sum?'hacia delante':'hacia atrás'} dos pasos.</p>${line(0,10,{...p,showSteps:done},false,a.a,a.answer)}${done?`<p class="notice">${a.a} → ${sum?4:4} → ${a.answer}. Dos saltos.</p>`:''}<div class="row">${button('Entender los signos','signs','secondary')}${button('Practicar a mi ritmo','guide-finish','',done?'':'disabled')}</div></section>${companion('Toca, cuenta y comprueba. Puedes volver a este ejemplo cuando quieras.')}</div>`;}
function current(ctx){const p=ctx.state.pending;return p.kind==='counting'?ctx.math.counting.find(x=>x.id===p.id):ctx.math.arithmetic.find(x=>x.id===p.id);}
function check(ctx){const p=ctx.state.pending;if(p.correct||p.answer==='')return;const a=current(ctx);if(Number(p.answer)===a.answer){p.correct=true;p.feedback=a.explanation;if(p.kind!=='counting')p.touched=Array.from({length:a.b},(_,i)=>i);ctx.attempt(p.kind,p.id,true);ctx.save();ctx.render();}else{p.errors++;p.feedback=a.hint;p.showHelp=true;ctx.save();ctx.render();}}
export function mathAction(ctx,action,b){if(action==='table'){ctx.state.tableNumber=+b.dataset.value;ctx.save();ctx.render();if(ctx.state.settings.sound)ctx.speak(numberName(+b.dataset.value));return true;}if(action==='line-speak'){if(ctx.state.settings.sound)ctx.speak(numberName(+b.dataset.value));return true;}if(action==='signs'){showDialog(`<h2>Los signos cuentan lo que pasa</h2><p class="instruction"><strong>+</strong> Más: juntamos o añadimos.<br><strong>−</strong> Menos: retiramos una parte.<br><strong>=</strong> Igual: ambos lados tienen el mismo valor.</p><div class="equation">3 + 2 = 5</div><p>Tres fichas y dos fichas representan la misma cantidad que cinco fichas.</p><div class="row"><div class="objects" aria-label="Tres fichas y dos fichas"><span>● ● ●</span><strong>+</strong><span>● ●</span></div><strong>=</strong><span aria-label="Cinco fichas">● ● ● ● ●</span></div>${audioButton('El signo más indica que juntamos o añadimos. El signo menos indica que retiramos una parte. El signo igual nos dice que ambos lados representan la misma cantidad. Tres más dos es igual a cinco.')}`);return true;}
const p=ctx.state.pending;if(!p||!['counting','sum','subtract','guide'].includes(p.kind))return false;
if(action==='count-object'){if(p.correct)return true;const n=+b.dataset.value;const i=p.touched.indexOf(n);if(i>=0)p.touched.splice(i,1);else p.touched.push(n);ctx.save();ctx.render();if(i<0&&ctx.state.settings.sound)ctx.speak(numberName(p.touched.length));}
else if(action==='operate'){if(p.correct)return true;const a=p.kind==='guide'?{b:2,kind:p.id}:current(ctx);const n=+b.dataset.value,i=p.touched.indexOf(n);if(i>=0)p.touched.splice(i,1);else if(p.touched.length<a.b)p.touched.push(n);else ctx.toast(`Ya has ${a.kind==='sum'?'añadido':'retirado'} ${a.b}. Ahora cuenta la cantidad que queda en el grupo.`);ctx.save();ctx.render();}
else if(action==='number-answer'){p.answer=b.dataset.value;check(ctx);}
else if(action==='key'){p.keypad=true;if(b.dataset.value==='✓')check(ctx);else{p.answer=b.dataset.value==='⌫'?p.answer.slice(0,-1):(p.answer+b.dataset.value).slice(0,3);ctx.save();ctx.render();}}
else if(action==='line-answer'){p.answer=b.dataset.value;ctx.save();ctx.render();}
else if(action==='math-check')check(ctx);
else if(action==='math-hint'){p.help=true;p.showHelp=true;p.feedback=current(ctx).hint;ctx.save();ctx.render();}
else if(action==='math-help'){p.help=true;p.showHelp=true;ctx.save();ctx.render();}
else if(action==='group-ten'){const a=current(ctx);p.grouped=(p.grouped||0)+1;ctx.save();ctx.render();if(ctx.state.settings.sound)ctx.speak(`${p.grouped} ${p.grouped===1?'decena':'decenas'} y ${a.number-p.grouped*10} unidades sueltas.`);}
else if(action==='show-steps'){p.showSteps=true;p.help=true;ctx.save();ctx.render();}
else if(action==='math-solution'){const a=current(ctx);p.help=true;p.showHelp=true;p.showSteps=true;p.solutionShown=true;p.correct=true;p.answer=String(a.answer);p.feedback=a.explanation;if(p.kind==='counting'){if(a.type==='objects')p.touched=Array.from({length:a.target},(_,i)=>i);if(a.type==='tens')p.grouped=Math.floor(a.number/10);}else p.touched=Array.from({length:a.b},(_,i)=>i);ctx.attempt(p.kind,p.id,true,{solutionShown:true});ctx.save();ctx.render();}
else if(action==='math-next')ctx.finish();
else if(action==='guide-finish'){ctx.state.guided=[...new Set([...(ctx.state.guided||[]),p.id])];ctx.state.pending=null;ctx.save();if(p.nextTask)ctx.start(p.nextTask.kind,p.nextTask.id);else ctx.go(p.id);}
else return false;return true;}
